import { Box, Button, Divider, Fade, Modal, useTheme } from '@mui/material';
import { useState } from 'react';

import { useAuth } from '../../../services/AuthService';
import { useInputFiles } from '../../../services/InputFilesContextProvider';
import { useStore } from '../../../services/StoreService';
import { StyledTab, StyledTabs } from '../../../shared/components/Tabs/StyledTabs';
import { SimulationFetchSource, SimulatorType } from '../../../types/RequestTypes';
import { SimulationInputFiles } from '../../../types/ResponseTypes';
import { InputFilesEditor } from '../InputEditor/InputFilesEditor';
import { inputFilesZipName, saveInputFilesAsZip } from '../InputEditor/saveInputFiles';
import { InputFiles } from '../InputEditor/simulatorDetection';
import { Geant4LocalWorkerSimulationsGrid } from './SimulationsGrid/Geant4LocalWorkerSimulationsGrid';
import { useIsBackendAlive } from './SimulationsGrid/hooks/useBackendAliveEffect';
import { RemoteWorkerSimulationsGrid } from './SimulationsGrid/RemoteWorkerSimulationsGrid';

interface SimulationPanelProps {
	goToResults?: () => void;
	source: SimulationFetchSource;
	setSource: (source: SimulationFetchSource) => void;
}

export default function SimulationPanel({ goToResults, source, setSource }: SimulationPanelProps) {
	const theme = useTheme();
	const { yaptideEditor } = useStore();
	const auth = useAuth();
	const [showInputFilesEditor, setShowInputFilesEditor] = useState(false);
	const [inputFiles, setInputFiles] = useState<SimulationInputFiles>();
	const [inputFilesTitle, setInputFilesTitle] = useState<string>();
	const isBackendAlive = useIsBackendAlive();
	const { addFiles } = useInputFiles();
	const modalInputFiles = (inputFiles ?? {}) as InputFiles;

	const showSimulationInputFiles = (files: SimulationInputFiles | undefined, title?: string) => {
		setInputFiles(files);
		setInputFilesTitle(title || undefined);
	};

	return (
		<Box
			sx={{
				width: '100%',
				height: '100%',
				boxSizing: 'border-box',
				display: 'flex',
				flexDirection: 'column'
			}}>
			<Modal
				aria-labelledby='transition-modal-title'
				aria-describedby='transition-modal-description'
				open={showInputFilesEditor}
				onClose={() => setShowInputFilesEditor(false)}
				closeAfterTransition>
				<Fade in={showInputFilesEditor}>
					<Box
						sx={{
							height: '90vh',
							width: '80vw',
							overflow: 'hidden',
							backgroundColor: theme.palette.background.paper,
							borderStyle: 'solid',
							borderColor: theme.palette.divider,
							borderWidth: 1,
							borderRadius: theme.spacing(1),
							my: '5vh',
							mx: '10vw',
							boxShadow: theme.shadows[10]
						}}>
						<Box
							sx={{
								height: '100%',
								width: '100%',
								padding: theme.spacing(1),
								overflowY: 'scroll',
								boxSizing: 'border-box'
							}}>
							<Box
								sx={{
									display: 'flex',
									justifyContent: 'flex-end',
									gap: theme.spacing(1),
									marginBottom: theme.spacing(1)
								}}>
								<Button
									color='primary'
									variant='contained'
									onClick={async () => {
										if (
											await addFiles(
												modalInputFiles,
												'replace',
												'Using the input files of this simulation',
												inputFilesTitle
											)
										)
											setShowInputFilesEditor(false);
									}}>
									Use these input files
								</Button>
								<Button
									color='info'
									onClick={() =>
										saveInputFilesAsZip(
											modalInputFiles,
											inputFilesZipName(
												inputFilesTitle ?? 'simulation',
												modalInputFiles,
												undefined
											)
										)
									}>
									Download all
								</Button>
								<Button
									color='info'
									onClick={() => setShowInputFilesEditor(false)}>
									Close
								</Button>
							</Box>
							<Divider />
							<InputFilesEditor
								inputFiles={modalInputFiles}
								onChange={(name, content) =>
									setInputFiles(
										old => ({ ...old, [name]: content }) as SimulationInputFiles
									)
								}
							/>
						</Box>
					</Box>
				</Fade>
			</Modal>

			{isBackendAlive && auth.isAuthorized && (
				<StyledTabs
					value={source}
					onChange={(_, v) => setSource(v)}
					sx={{ m: 1 }}>
					<StyledTab
						label='Simulations from server'
						value='remote'
						key='remote'
					/>
					<StyledTab
						label='Local simulations'
						value='local'
						key='local'
					/>
				</StyledTabs>
			)}

			{source === 'remote' ? (
				<RemoteWorkerSimulationsGrid
					goToResults={goToResults}
					setShowInputFilesEditor={setShowInputFilesEditor}
					setInputFiles={showSimulationInputFiles}
					simulator={
						yaptideEditor?.contextManager.currentSimulator || SimulatorType.COMMON
					}
				/>
			) : (
				<Geant4LocalWorkerSimulationsGrid
					goToResults={goToResults}
					setInputFiles={showSimulationInputFiles}
					setShowInputFilesEditor={setShowInputFilesEditor}
					simulator={SimulatorType.GEANT4}
				/>
			)}
		</Box>
	);
}
