import './SidebarTreeList.style.css';

import { DropOptions, Tree, TreeMethods } from '@minoru/react-dnd-treeview';
import { Box } from '@mui/material';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Object3D } from 'three';
import { generateUUID } from 'three/src/math/MathUtils.js';

import { useSignal } from '../../../../util/hooks/signals';
import { MoveObjectInTreeCommand } from '../../../js/commands/MoveObjectInTreeCommand';
import { YaptideEditor } from '../../../js/YaptideEditor';
import {
	isSimulationSceneContainer,
	SimulationSceneChild
} from '../../../Simulation/Base/SimulationContainer';
import { SidebarTreeListItem, TreeItem, TreeItemData } from './SidebarTreeListItem';
import { useGenerateTreeData } from './useGenerateTreeData';

type TreeSource = SimulationSceneChild[];

function getTreeAncestorIds(object: Object3D | null, sources: TreeSource): number[] {
	const ancestorIds: number[] = [];

	for (let parent = object?.parent; parent; parent = parent.parent) {
		if (!isSimulationSceneContainer(parent) || !parent.flattenOnOutliner) {
			ancestorIds.push(parent.id);
		}

		if (sources.includes(parent as SimulationSceneChild)) {
			return ancestorIds;
		}
	}

	return [];
}

function Placeholder() {
	return (
		<Box
			// to make the box visible using margins, it would increase the height to > 0
			// boxShadow doesn't change the height and prevent rows from moving to make space
			// and can be made to look them same
			sx={theme => ({ height: 0, boxShadow: `0 0 0 1px ${theme.palette.secondary.main}` })}
		/>
	);
}

export function SidebarTreeList(props: {
	editor: YaptideEditor;
	sources: TreeSource;
	dragDisabled?: boolean;
	nestingAllowed?: boolean;
	sortingDisabled?: boolean;
}) {
	const { editor, sources, nestingAllowed, sortingDisabled } = props;

	const treeId = useMemo(() => generateUUID(), []);
	const [treeData, refreshTreeData] = useGenerateTreeData(treeId, sources);
	const treeRef = useRef<TreeMethods>(null);

	const [initialOpenIds] = useState(() => getTreeAncestorIds(editor.selected, sources));

	const handleSelected = useCallback(
		(object: Object3D | null) => {
			if (!object) {
				return;
			}

			const ancestorIds = getTreeAncestorIds(object, sources);

			if (ancestorIds.length > 0) {
				treeRef.current?.open(ancestorIds);
			}

			document
				.getElementById(object.uuid)
				?.scrollIntoView({ behavior: 'smooth', block: 'center' });
		},
		[sources]
	);

	useSignal(editor, 'objectSelected', handleSelected);

	useEffect(() => {
		refreshTreeData();

		editor.signals.editorCleared.add(refreshTreeData);
		editor.signals.objectChanged.add(refreshTreeData);
		editor.signals.objectAdded.add(refreshTreeData);
		editor.signals.objectRemoved.add(refreshTreeData);

		return () => {
			editor.signals.editorCleared.remove(refreshTreeData);
			editor.signals.objectChanged.remove(refreshTreeData);
			editor.signals.objectAdded.remove(refreshTreeData);
			editor.signals.objectRemoved.remove(refreshTreeData);
		};
	}, [editor, refreshTreeData]);

	const handleDrop = useCallback(
		(
			tree: TreeItem[],
			dragDestination: {
				dragSource?: TreeItem;
				dropTarget?: TreeItem;
				relativeIndex?: number;
			}
		) => {
			const { dragSource, dropTarget, relativeIndex } = dragDestination;

			if (relativeIndex === undefined) {
				return console.warn(
					'relativeIndex is undefined; check if sort option is set to false.'
				);
			}

			if (!dragSource?.data) {
				return;
			}

			const findObjectById = (id: string | number) => {
				for (const node of tree) {
					if (node.id === id) {
						return node;
					}
				}

				return null;
			};

			const dragObject = findObjectById(dragSource.id)!;

			// The outliner may flatten containers (e.g. QuantityContainer), so the tree parent
			// isn't always the real Object3D parent. When reordering in place, keep the real one.
			const isReorderInPlace = dragSource.parent === (dropTarget?.id ?? 0);
			const newParent = isReorderInPlace
				? dragSource.data.object.parent
				: dropTarget
					? findObjectById(dropTarget.id)!.data!.object
					: null;

			if (
				dragObject.parent !== dragSource.parent ||
				(relativeIndex !== dragSource.data.index &&
					relativeIndex - 1 !== dragSource.data.index)
			) {
				editor.execute(
					new MoveObjectInTreeCommand(
						editor,
						dragSource.data.object,
						relativeIndex > (dragSource.data.index ?? 0)
							? relativeIndex - 1
							: relativeIndex,
						newParent
					)
				);
			}
		},
		[editor]
	);

	const canDrop = useCallback(
		(_: any, options: DropOptions<TreeItemData>): boolean | void => {
			const { dragSource, dropTargetId } = options;

			if (sortingDisabled) {
				return false;
			}

			if (dragSource?.parent === dropTargetId) {
				// allow for reordering within current parent
				return true;
			}

			if (
				!dragSource ||
				dragSource.data?.treeId !== treeId ||
				(dragSource?.parent !== dropTargetId && !nestingAllowed)
			) {
				// sanity checks and obvious violations
				return false;
			}

			return; // let the default library logic handle the rest, i.e. moving subtree into itself
		},
		[treeId, nestingAllowed, sortingDisabled]
	);

	return (
		<Tree
			ref={treeRef}
			initialOpen={initialOpenIds}
			classes={{
				root: 'editor-sidebar-tree',
				dropTarget: 'editor-sidebar-drop-target'
			}}
			tree={treeData}
			rootId={0}
			sort={!!sortingDisabled}
			onDrop={handleDrop}
			canDrop={canDrop}
			dropTargetOffset={5}
			placeholderRender={Placeholder}
			render={(node, { depth, isOpen, onToggle, hasChild }) => (
				<SidebarTreeListItem
					node={node}
					depth={depth}
					hasChild={hasChild}
					isOpen={isOpen}
					onToggle={onToggle}
					editor={editor}
				/>
			)}
		/>
	);
}
